import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.BZO4qERu.js";const i="/images/tokeness-api-keys-light-16x9.png",r="/images/tokeness-api-keys-dark-16x9.png",b=JSON.parse('{"title":"API 密钥","description":"Tokeness API Key 创建、命名、额度、轮换和环境变量配置说明。","frontmatter":{"title":"API 密钥","description":"Tokeness API Key 创建、命名、额度、轮换和环境变量配置说明。"},"headers":[],"relativePath":"guide/api-keys.md","filePath":"guide/api-keys.md","lastUpdated":1781532219000}'),o={name:"guide/api-keys.md"};function l(n,t,h,p,c,k){return a(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="api-密钥" tabindex="-1">API 密钥 <a class="header-anchor" href="#api-密钥" aria-label="Permalink to &quot;API 密钥&quot;">​</a></h1><p>API Key 是 Tokeness 的调用凭证。每个 Key 需要有明确用途，避免多个项目共用同一个 Key。</p><figure class="tokeness-shot"><div class="tokeness-shot-frame"><img class="tokeness-shot-light" src="'+i+'" alt="Tokeness API 密钥页"><img class="tokeness-shot-dark" src="'+r+`" alt="Tokeness API 密钥页"></div><figcaption>API 密钥页</figcaption></figure><h2 id="创建-key" tabindex="-1">创建 Key <a class="header-anchor" href="#创建-key" aria-label="Permalink to &quot;创建 Key&quot;">​</a></h2><ol><li>登录 <a href="https://tokeness.cn" target="_blank" rel="noreferrer">tokeness.cn</a>。</li><li>打开控制台左侧“API 密钥”。</li><li>点击创建或添加密钥。</li><li>填写名称、额度、分组或模型范围。</li><li>创建后立即保存密钥。</li></ol><p>还没接入正式业务时，可以先创建两个 Key：</p><table tabindex="0"><thead><tr><th>场景</th><th>配置方式</th></tr></thead><tbody><tr><td>测试</td><td>小额度，方便试错</td></tr><tr><td>正式</td><td>独立 Key，避免和测试混用</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">安全提醒</p><p>API Key 属于敏感凭证。不要把 Key 写入前端代码、公开仓库、截图、工单图片或群聊消息。</p></div><h2 id="列表字段" tabindex="-1">列表字段 <a class="header-anchor" href="#列表字段" aria-label="Permalink to &quot;列表字段&quot;">​</a></h2><p>API 密钥页会展示每个 Key 的主要管理信息：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>Key 的用途名称，例如开发、生产或某个客户</td></tr><tr><td>状态</td><td>Key 是否启用</td></tr><tr><td>API 密钥</td><td>掩码后的 Key，可用于确认是否选对凭证</td></tr><tr><td>额度</td><td>当前 Key 的额度限制</td></tr><tr><td>分组</td><td>Key 所属模型或计费分组</td></tr><tr><td>模型</td><td>当前 Key 可用模型范围</td></tr><tr><td>IP 限制</td><td>是否限制调用来源 IP</td></tr><tr><td>创建时间</td><td>Key 创建时间</td></tr><tr><td>最后使用时间</td><td>最近一次调用时间</td></tr><tr><td>过期</td><td>Key 的过期策略</td></tr></tbody></table><h2 id="命名规则" tabindex="-1">命名规则 <a class="header-anchor" href="#命名规则" aria-label="Permalink to &quot;命名规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>Key 名称示例</th></tr></thead><tbody><tr><td>本地开发</td><td><code>dev-local</code></td></tr><tr><td>生产服务</td><td><code>prod-api-gateway</code></td></tr><tr><td>客户项目</td><td><code>client-acme-prod</code></td></tr><tr><td>自动化任务</td><td><code>n8n-workflows</code></td></tr></tbody></table><h2 id="额度策略" tabindex="-1">额度策略 <a class="header-anchor" href="#额度策略" aria-label="Permalink to &quot;额度策略&quot;">​</a></h2><p>开发和测试 Key 设置较小额度。生产 Key 按业务体量设置上限。渠道或多客户场景下，每个客户使用独立 Key，便于核算消耗。</p><h2 id="轮换-key" tabindex="-1">轮换 Key <a class="header-anchor" href="#轮换-key" aria-label="Permalink to &quot;轮换 Key&quot;">​</a></h2><p>当 Key 泄露、成员离职、项目交接或环境迁移时，应创建新 Key 并替换旧配置。确认新 Key 生效后，再停用旧 Key。</p><h2 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h2><p>服务端项目使用环境变量保存：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKENESS_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKENESS_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://n.tokeness.io/v1</span></span></code></pre></div><p>不要把 <code>.env</code> 文件提交到 Git 仓库。</p>`,21)])])}const K=e(o,[["render",l]]);export{b as __pageData,K as default};
